'use client';

import { useEffect, useRef } from 'react';
import { createNilkamal } from './create-nilkamal';
import type { FrameState } from './engine/runtime';
import type { Weather } from './weather';
import './scene.css';

export type NilkamalController = ReturnType<typeof createNilkamal>;
export type NilkamalProps = {
  weather?: Weather;
  intensity?: number;
  seed?: number;
  paused?: boolean;
  enableAudio?: boolean;
  volume?: number;
  className?: string;
  fallback?: string;
  onReady?: (controller: NilkamalController | null) => void;
  onFrame?: (frame: FrameState) => void;
  onError?: (error: Error) => void;
};

/** Weather, pause, and audio props update the existing scene. Keep callbacks stable. */
export function Nilkamal({ weather = 'clear', intensity = .8, seed = 731, paused = false, enableAudio = true, volume = .45, className = '', fallback, onReady, onFrame, onError }: NilkamalProps) {
  const canvas = useRef<HTMLCanvasElement>(null);
  const controller = useRef<NilkamalController | null>(null);
  useEffect(() => {
    if (!canvas.current) return;
    let instance: NilkamalController;
    try { instance = createNilkamal(canvas.current, { seed, onFrame }); }
    catch (error) { onError?.(error instanceof Error ? error : new Error(String(error))); return; }
    controller.current = instance;
    onReady?.(instance);
    return () => { instance.destroy(); controller.current = null; onReady?.(null); };
  }, [seed, onFrame, onReady, onError]);
  useEffect(() => { if (paused) controller.current?.pause(); else controller.current?.resume(); }, [paused, seed, onFrame, onReady, onError]);
  useEffect(() => { controller.current?.setWeather(weather); }, [weather, seed, onFrame, onReady, onError]);
  useEffect(() => { controller.current?.setIntensity(intensity); }, [intensity, seed, onFrame, onReady, onError]);
  useEffect(() => { controller.current?.setAudio(enableAudio, volume); }, [enableAudio, volume, seed, onFrame, onReady, onError]);
  return <div className={`nilkamal-scene ${className}`}>
    {fallback && <img className="nilkamal-fallback" src={fallback} alt="" aria-hidden="true" />}
    <canvas ref={canvas} role="img" aria-label="One blue lotus on a pond. Hover over its petals, pull the flower, or touch the water. The lotus and pond have buttons for keyboard interaction." />
  </div>;
}

export { WEATHERS, type Weather } from './weather';
export { NILKAMAL_LAYERS } from './scene';

import { createNilkamalAudio } from './audio';
import { mountNilkamal, type NilkamalSceneOptions } from './scene';
import type { RuntimeOptions } from './engine/runtime';

export type NilkamalOptions = Omit<NilkamalSceneOptions, 'onEvent'> & RuntimeOptions & { enableAudio?: boolean; volume?: number };

export function createNilkamal(canvas: HTMLCanvasElement, options: NilkamalOptions = {}) {
  const audio = createNilkamalAudio(options.enableAudio ?? true, options.volume ?? .45);
  const events = new AbortController();
  audio.setWeather(options.weather ?? 'clear');
  audio.setIntensity(options.intensity ?? .8);
  let runtime: ReturnType<typeof mountNilkamal>;
  try { runtime = mountNilkamal(canvas, { ...options, onEvent: audio.event, onFrame(frame) { audio.setActive(frame.running); options.onFrame?.(frame); } }); }
  catch (error) { audio.destroy(); throw error; }
  const unlock = () => { void audio.unlock().catch(() => {}); };
  canvas.parentElement?.addEventListener('pointerdown', unlock, { signal: events.signal, capture: true });
  canvas.parentElement?.addEventListener('keydown', unlock, { signal: events.signal, capture: true });
  return { ...runtime,
    unlockAudio: audio.unlock,
    setAudio: audio.setAudio,
    setWeather(weather: Parameters<typeof runtime.setWeather>[0]) { runtime.setWeather(weather); audio.setWeather(weather); },
    setIntensity(intensity: number) { runtime.setIntensity(intensity); audio.setIntensity(intensity); },
    snapshot() { return { ...runtime.snapshot(), audio: audio.snapshot() }; },
    destroy() { events.abort(); runtime.destroy(); audio.destroy(); },
  };
}

import { chainSnapshot, createChain, resetChain, simulateChain } from './engine/elastic';
import { clamp, mix, randomSource, TAU, type Point } from './engine/math';
import { mountScene, type PaintState, type RuntimeOptions, type SceneDefinition, type SceneInput } from './engine/runtime';
import { drawLotus } from './lotus';
import { createWeather, stepWeather, strikeLightning, type Weather, type WeatherEvent } from './weather';

export const NILKAMAL_SIZE = { width: 1000, height: 680 };
export const NILKAMAL_LAYERS = ['sky', 'landscape', 'water', 'ice', 'lotus', 'weather', 'foreground'] as const;
export type NilkamalLayer = typeof NILKAMAL_LAYERS[number];
export type NilkamalSceneOptions = { weather?: Weather; intensity?: number; seed?: number; onEvent?: (event: WeatherEvent) => void };

function pad(c: CanvasRenderingContext2D, x: number, y: number, r: number, rotation: number, snow: number, time: number) {
  c.save(); c.translate(x, y + Math.sin(time + x) * .45); c.scale(1, .245); c.rotate(rotation);
  c.beginPath(); c.moveTo(0, 0); c.arc(0, 0, r, .2, TAU - .16); c.closePath();
  const g = c.createRadialGradient(-r * .2, -r * .3, 0, 0, 0, r);
  g.addColorStop(0, '#3e6353'); g.addColorStop(.5, '#244a3f'); g.addColorStop(1, '#102c2c');
  c.fillStyle = g; c.fill(); c.strokeStyle = '#466d60'; c.lineWidth = 1.5; c.stroke();
  c.save(); c.clip();
  for (let i = 0; i < 25; i++) {
    const a = i / 25 * TAU;
    c.strokeStyle = 'rgba(111,160,121,.23)'; c.lineWidth = 1;
    c.beginPath(); c.moveTo(0, 0); c.quadraticCurveTo(Math.cos(a + .1) * r * .5, Math.sin(a + .1) * r * .5, Math.cos(a) * r, Math.sin(a) * r); c.stroke();
  }
  if (snow > .02) {
    c.fillStyle = `rgba(224,242,245,${snow * .87})`; c.fillRect(-r, -r, r * 2, r * 2);
    c.strokeStyle = `rgba(255,255,255,${snow})`; c.lineWidth = 5 + snow * 10;
    c.beginPath(); c.arc(0, 0, r - 3, Math.PI, TAU); c.stroke();
  }
  c.restore(); c.restore();
}

function iceBranch(c: CanvasRenderingContext2D, x: number, y: number, length: number, angle: number, depth: number, progress: number) {
  if (depth === 0 || progress <= 0) return;
  const endX = x + Math.cos(angle) * length * Math.min(1, progress), endY = y + Math.sin(angle) * length * .4 * Math.min(1, progress);
  c.beginPath(); c.moveTo(x, y); c.lineTo(endX, endY); c.stroke();
  if (progress > .3) {
    for (const side of [-1, 1]) iceBranch(c, mix(x, endX, .55), mix(y, endY, .55), length * .58, angle + side * .68, depth - 1, (progress - .3) * 1.4);
  }
}

export function createNilkamalScene(options: NilkamalSceneOptions = {}) {
  const seed = options.seed ?? 731;
  if (!Number.isInteger(seed) || seed < 0 || seed > 4294967295) throw new Error('Seed must be an unsigned 32-bit integer.');
  const random = randomSource(seed);
  const w = createWeather(seed, options.weather ?? 'clear', options.intensity ?? .8);
  const chain = createChain(Array.from({ length: 9 }, (_, i) => ({ x: 500 + Math.sin(i / 8 * Math.PI) * 5, y: 560 - i / 8 * 120 })), 74);
  const stars = Array.from({ length: 85 }, () => ({ x: random() * 1000, y: random() * 295, r: .3 + random() * 1.1, phase: random() * TAU }));
  const reeds = Array.from({ length: 65 }, () => ({ x: random() < .5 ? random() * 190 : 810 + random() * 190, y: 645 + random() * 65, h: 35 + random() * 140, phase: random() * TAU }));
  const iceSites = Array.from({ length: 16 }, (_, i) => ({ x: i % 2 ? 1030 : -30, y: 385 + random() * 290, length: 160 + random() * 230, angle: i % 2 ? Math.PI + random() * .7 - .35 : random() * .7 - .35 }));
  const fireflies = Array.from({ length: 20 }, () => ({ x: 220 + random() * 560, y: 280 + random() * 340, phase: random() * TAU }));
  const onEvent = options.onEvent ?? (() => {});
  const grainCanvas = document.createElement('canvas'); grainCanvas.width = grainCanvas.height = 96;
  const grainContext = grainCanvas.getContext('2d');
  if (!grainContext) throw new Error('Canvas 2D is unavailable.');
  const pixels = grainContext.createImageData(96, 96);
  for (let i = 0; i < pixels.data.length; i += 4) { const value = Math.floor(random() * 255); pixels.data[i] = pixels.data[i + 1] = pixels.data[i + 2] = value; pixels.data[i + 3] = 90; }
  grainContext.putImageData(pixels, 0, 0);
  const maybeTexture = grainContext.createPattern(grainCanvas, 'repeat');
  if (!maybeTexture) throw new Error('Could not create the petal texture.');
  const texture = maybeTexture;
  let time = 0, bloom = 1, hover = 0, localPointer: Point | null = null, impulse: { target: Point; until: number } | null = null;
  let lastPointer: Point | null = null, lastRipple = 0, lastDrag = false;
  const head = () => chain.nodes.at(-1) ?? { x: 500, y: 440 };

  function inspect() {
    return { seed, weather: w.selected, intensity: w.intensity, rain: w.rain, wind: w.wind, snow: w.snow, ice: w.ice, wetness: w.wetness, lightning: w.flash, bloom, hover, ripples: w.ripples.length, drops: w.drops.length, lotus: chainSnapshot(chain) };
  }

  function flower(c: CanvasRenderingContext2D, reflection: boolean) {
    const tip = head();
    c.save();
    if (reflection) { c.translate(0, 684); c.scale(1, -.42); c.globalAlpha *= .2 * (1 - w.ice); }
    c.translate(tip.x, tip.y); c.rotate(chain.headAngle * .22);
    drawLotus(c, { time, wind: w.wind, snow: w.snow, wetness: w.wetness, bloom, hover, flash: w.flash, pointer: localPointer, texture });
    c.restore();
  }

  const scene = {
    size: NILKAMAL_SIZE, layers: NILKAMAL_LAYERS,
    update(elapsed: number, reset: boolean) {
      time = elapsed;
      if (reset) { resetChain(chain); impulse = null; lastPointer = localPointer = null; }
    },
    step(dt: number, physicalTime: number, input: SceneInput) {
      const tip = head();
      stepWeather(w, dt, physicalTime, onEvent, tip);
      const near = input.pointer ? Math.max(0, 1 - Math.hypot(input.pointer.x - tip.x, input.pointer.y - (tip.y - 90)) / 180) : 0;
      if (hover < .2 && near > .6) onEvent('lotus');
      hover = mix(hover, near, 1 - Math.exp(-dt * 5));
      localPointer = input.pointer ? { x: input.pointer.x - tip.x, y: input.pointer.y - tip.y } : null;
      const dragged = input.drag?.id === 'lotus';
      if (input.drag && !lastDrag) {
        if (dragged) onEvent('lotus');
        else { w.ripples.push({ x: input.drag.target.x, y: input.drag.target.y, age: 0, power: 1 }); onEvent(w.ice > .6 ? 'ice' : 'water'); }
      }
      lastDrag = Boolean(input.drag);
      const target = dragged && input.drag ? { x: input.drag.target.x, y: input.drag.target.y + 92 } : impulse && physicalTime < impulse.until ? impulse.target : input.pointer && near > 0 ? { x: 500 + (input.pointer.x - tip.x) * .3 * near, y: 440 + near * 3 } : null;
      simulateChain(chain, dt, physicalTime, w.wind * 1.9, target);
      if (input.pointer && input.pointer.y > 370 && physicalTime - lastRipple > .09 && w.ice < .85) {
        const distance = lastPointer ? Math.hypot(input.pointer.x - lastPointer.x, input.pointer.y - lastPointer.y) : 0;
        if (distance > 9 && w.ripples.length < 65) {
          w.ripples.push({ ...input.pointer, age: 0, power: .65 }); lastRipple = physicalTime;
          if (distance > 35) onEvent('water');
        }
      }
      lastPointer = input.pointer;
    },
    targets() {
      const tip = head();
      return [{ id: 'lotus', label: 'Pull the blue lotus. Press Enter to bend it.', x: tip.x, y: tip.y - 92, radius: 128 },
        { id: 'pond', label: w.ice > .6 ? 'Tap the ice' : 'Make a ripple in the pond', x: 500, y: 586, radius: 48 }];
    },
    activate(id: string, direction: number, physicalTime: number) {
      if (id === 'lotus') { impulse = { target: { x: 500 + 64 * direction, y: 446 }, until: physicalTime + .75 }; onEvent('lotus'); }
      else if (id === 'pond') { w.ripples.push({ x: 500, y: 586, age: 0, power: 1 }); onEvent(w.ice > .6 ? 'ice' : 'water'); }
    },
    release() { impulse = null; lastDrag = false; lastPointer = localPointer = null; },
    inspect,
    setWeather(weather: Weather, instant = false) {
      w.selected = weather;
      if (instant) {
        w.rain = weather === 'rain' || weather === 'storm' ? 1 : 0;
        w.cold = weather === 'snow' || weather === 'hail' ? 1 : 0;
        w.storm = weather === 'storm' ? 1 : 0;
        w.wind = .12 + w.storm * 2 + w.cold * .3;
        w.snow = w.cold ? Math.max(w.snow, .6) : 0;
        w.ice = w.cold ? Math.max(w.ice, .5) : 0;
        w.wetness = w.rain; w.flash = 0;
      }
      onEvent('weather');
    },
    setIntensity(intensity: number) { if (!Number.isFinite(intensity)) throw new Error('Intensity must be finite.'); w.intensity = clamp(intensity, .2, 1); },
    setBloom(value: number) { bloom = clamp(value); },
    lightning() { strikeLightning(w); onEvent('thunder'); },
    reset() {
      w.snow = w.ice = w.wetness = w.flash = 0; w.ripples.length = w.drops.length = 0;
      w.nextThunder = 5; w.nextIce = 4; resetChain(chain); bloom = 1;
    },
    paint(c: CanvasRenderingContext2D, state: PaintState, layers: ReadonlySet<NilkamalLayer>) {
      c.lineCap = 'round';
      const cold = w.cold, storm = w.storm;
      if (layers.has('sky')) {
        const g = c.createLinearGradient(0, 0, 0, 680);
        g.addColorStop(0, `rgb(${Math.round(5 + cold * 12)},${Math.round(15 + cold * 12)},${Math.round(27 + cold * 18)})`);
        g.addColorStop(.48, `rgb(${Math.round(20 + cold * 15 - storm * 12)},${Math.round(44 + cold * 13 - storm * 24)},${Math.round(57 + cold * 17 - storm * 24)})`);
        g.addColorStop(1, '#071820'); c.fillStyle = g; c.fillRect(0, 0, 1000, 680);
        c.save(); c.globalAlpha = (1 - Math.max(storm, w.rain * .6, cold * .8));
        for (const s of stars) {
          c.fillStyle = `rgba(190,219,230,${.3 + Math.sin(time * .6 + s.phase) * .2})`;
          c.beginPath(); c.arc(s.x, s.y, s.r, 0, TAU); c.fill();
        }
        const glow = c.createRadialGradient(731, 114, 4, 731, 114, 140);
        glow.addColorStop(0, 'rgba(185,217,211,.16)'); glow.addColorStop(1, 'rgba(185,217,211,0)');
        c.fillStyle = glow; c.fillRect(590, 0, 282, 255);
        const moon = c.createRadialGradient(727, 108, 1, 731, 114, 23);
        moon.addColorStop(0, '#e4e9d9'); moon.addColorStop(1, '#acbfbc'); c.fillStyle = moon;
        c.beginPath(); c.arc(731, 114, 22, 0, TAU); c.fill();
        c.fillStyle = 'rgba(86,122,128,.1)';
        for (let i = 0; i < 8; i++) { c.beginPath(); c.arc(720 + (i * 13 % 23), 101 + (i * 7 % 24), 2 + i % 3, 0, TAU); c.fill(); }
        c.restore();
        for (let i = 0; i < 6; i++) {
          const cx = ((i * 221 + time * (5 + storm * 13)) % 1420) - 220;
          const cloud = c.createRadialGradient(cx, 108 + i * 24, 3, cx, 108 + i * 24, 230);
          cloud.addColorStop(0, `rgba(97,127,143,${.025 + Math.max(w.rain, cold) * .12})`); cloud.addColorStop(1, 'rgba(60,83,110,0)');
          c.save(); c.translate(cx, 108 + i * 24); c.scale(1, .3); c.fillStyle = cloud;
          c.translate(-cx, -(108 + i * 24)); c.fillRect(cx - 240, -160, 480, 600); c.restore();
        }
      }
      if (layers.has('landscape')) {
        for (let layer = 0; layer < 4; layer++) {
          c.beginPath(); c.moveTo(-10, 360);
          for (let x = -10; x <= 1010; x += 10) {
            const height = 60 + Math.sin(x * .004 + layer * 1.4) * 45 + Math.sin(x * .014 + layer) * 18 + Math.sin(x * .028) * 6;
            c.lineTo(x, 313 + layer * 17 - height * (1 - layer * .16));
          }
          c.lineTo(1010, 386); c.lineTo(-10, 386); c.closePath();
          c.fillStyle = `rgb(${12 - layer * 2 + Math.round(cold * 7)},${32 - layer * 5 + Math.round(cold * 9)},${44 - layer * 5 + Math.round(cold * 11)})`; c.fill();
        }
        const mist = c.createLinearGradient(0, 285, 0, 400);
        mist.addColorStop(0, 'rgba(139,193,196,0)'); mist.addColorStop(.55, `rgba(114,168,181,${.1 + cold * .15})`); mist.addColorStop(1, 'rgba(114,168,181,0)');
        c.fillStyle = mist; c.fillRect(0, 280, 1000, 130);
      }
      if (layers.has('water')) {
        const water = c.createLinearGradient(0, 355, 0, 680);
        water.addColorStop(0, '#15313e'); water.addColorStop(.28, '#102b36'); water.addColorStop(1, '#040f19');
        c.fillStyle = water; c.fillRect(0, 355, 1000, 325);
        const glow = c.createRadialGradient(500, 465, 10, 500, 470, 250);
        glow.addColorStop(0, 'rgba(54,132,169,.16)'); glow.addColorStop(1, 'rgba(44,117,157,0)'); c.fillStyle = glow; c.fillRect(220, 355, 560, 325);
        flower(c, true);
        for (let i = 0; i < 130; i++) {
          const y = 358 + i * 2.6, wave = Math.sin(time * (1 + storm) + i * .62);
          const x = (i * 137 % 1100) - 50 + wave * (4 + storm * 7), len = 18 + (i * 71 % 100);
          c.strokeStyle = `rgba(120,175,191,${.04 + (i % 7 === 0 ? .035 : 0)})`; c.lineWidth = .65;
          c.beginPath(); c.moveTo(x, y); c.quadraticCurveTo(x + len * .5, y + wave * 1.2, x + len, y); c.stroke();
          if (i < 55) {
            c.strokeStyle = `rgba(195,221,209,${(1 - Math.max(w.rain, cold)) * .075})`;
            c.beginPath(); c.moveTo(730 - i * .27 + wave * 3, y); c.lineTo(730 + i * .27 + wave * 3, y); c.stroke();
          }
        }
        for (const r of w.ripples) {
          c.strokeStyle = `rgba(139,211,238,${(1 - r.age / 2.4) * .33 * (1 - w.ice)})`; c.lineWidth = .7;
          for (let ring = 0; ring < 2; ring++) {
            const radius = r.age * 24 * r.power - ring * 8;
            if (radius > 0) { c.beginPath(); c.ellipse(r.x, r.y, radius, radius * .24, 0, 0, TAU); c.stroke(); }
          }
        }
        pad(c, 499, 492, 141, -.06, w.snow, time * .5);
        pad(c, 242, 530, 74, .15, w.snow, time * .4);
        pad(c, 733, 461, 67, -.08, w.snow, time * .4);
        pad(c, 797, 601, 103, -.1, w.snow, time * .4);
        pad(c, 97, 631, 118, .2, w.snow, time * .4);
      }
      if (layers.has('ice') && w.ice > .01) {
        c.save();
        const ice = c.createLinearGradient(0, 370, 0, 680);
        ice.addColorStop(0, `rgba(168,210,228,${w.ice * .12})`); ice.addColorStop(1, `rgba(182,218,229,${w.ice * .65})`);
        c.fillStyle = ice; c.fillRect(0, 365, 1000, 315);
        for (const site of iceSites) {
          c.strokeStyle = `rgba(221,245,255,${w.ice * .32})`; c.lineWidth = .65;
          iceBranch(c, site.x, site.y, site.length, site.angle, 4, w.ice * 3);
          c.strokeStyle = `rgba(111,165,186,${w.ice * .17})`; c.lineWidth = 1.4;
          iceBranch(c, site.x, site.y + 1, site.length, site.angle, 4, w.ice * 3);
        }
        for (let i = 0; i < 80; i++) {
          const x = (i * 173) % 1000, y = 450 + (i * 41 % 230), radius = (3 + i % 7) * w.snow;
          c.fillStyle = `rgba(243,252,255,${w.snow * .27})`; c.beginPath(); c.ellipse(x, y, radius * 2, radius * .3, 0, 0, TAU); c.fill();
        }
        c.restore();
      }
      if (layers.has('lotus')) {
        const nodes = chain.nodes, root = nodes[0];
        if (root) {
          c.save(); c.beginPath(); c.rect(0, 0, 1000, 487); c.clip();
          c.strokeStyle = '#193d35'; c.lineWidth = 6; c.beginPath(); c.moveTo(root.x, root.y);
          for (let i = 1; i < nodes.length - 1; i++) { const node = nodes[i], next = nodes[i + 1]; if (node && next) c.quadraticCurveTo(node.x, node.y, (node.x + next.x) / 2, (node.y + next.y) / 2); }
          const tip = head(); c.lineTo(tip.x, tip.y); c.stroke();
          c.strokeStyle = '#5c8670'; c.lineWidth = 1.5; c.stroke(); c.restore();
          c.save(); c.translate(tip.x, tip.y + 5); c.rotate(chain.headAngle * .22);
          c.fillStyle = '#234b43'; c.beginPath(); c.moveTo(-25, -5); c.quadraticCurveTo(-8, 17, 0, 13); c.quadraticCurveTo(12, 11, 25, -5); c.quadraticCurveTo(0, 3, -25, -5); c.fill(); c.restore();
        }
        flower(c, false);
      }
      if (layers.has('weather')) {
        const precipitation = Math.max(w.rain, cold);
        const count = Math.round(w.particles.length * precipitation * w.intensity);
        for (let i = 0; i < count; i++) {
          const p = w.particles[i]; if (!p) continue;
          c.save(); c.globalAlpha = precipitation * (.24 + p.depth * .6);
          if (cold > .5) {
            const hail = w.selected === 'hail' || p.kind < .19;
            const radius = hail ? 1.8 + p.depth * 2.5 : .6 + p.depth * 2.6;
            c.fillStyle = hail ? '#deeffa' : '#f0f7fb';
            if (hail) { c.shadowColor = 'rgba(153,203,242,.5)'; c.shadowBlur = 4; }
            c.beginPath(); c.arc(p.x, p.y, radius, 0, TAU); c.fill();
            if (hail) { c.fillStyle = '#fff'; c.beginPath(); c.arc(p.x - .5, p.y - .7, radius * .35, 0, TAU); c.fill(); }
          } else {
            c.strokeStyle = 'rgba(165,212,240,.6)'; c.lineWidth = .55 + p.depth * .75;
            c.beginPath(); c.moveTo(p.x, p.y); c.lineTo(p.x - (2 + storm * 9) * p.depth, p.y - (9 + p.depth * 15)); c.stroke();
            if (p.depth > .84) { c.fillStyle = 'rgba(185,227,249,.65)'; c.beginPath(); c.ellipse(p.x, p.y, 1, 2.3, -.15 - storm * .3, 0, TAU); c.fill(); }
          }
          c.restore();
        }
        for (const p of w.drops) {
          c.fillStyle = 'rgba(152,222,251,.7)'; c.beginPath(); c.ellipse(p.x, p.y, 2, 3.7, -.15, 0, TAU); c.fill();
          c.fillStyle = '#d5f6ff'; c.beginPath(); c.arc(p.x - .5, p.y - 1.4, .65, 0, TAU); c.fill();
        }
        if (w.lightningAge < .32 && !state.reducedMotion) {
          c.save(); c.globalAlpha = Math.max(.1, w.flash); c.strokeStyle = '#def2ff'; c.lineWidth = 1.8; c.shadowColor = '#92cafa'; c.shadowBlur = 12;
          c.beginPath(); for (const [i, p] of w.lightning.entries()) { if (i === 0) c.moveTo(p.x, p.y); else c.lineTo(p.x, p.y); } c.stroke();
          const fork = w.lightning[6]; if (fork) { c.lineWidth = .75; c.beginPath(); c.moveTo(fork.x, fork.y); c.lineTo(fork.x + 60, fork.y + 25); c.lineTo(fork.x + 48, fork.y + 48); c.lineTo(fork.x + 110, fork.y + 81); c.stroke(); }
          c.restore();
        }
        if (w.flash > .001 && !state.reducedMotion) { c.fillStyle = `rgba(174,214,255,${w.flash * .2})`; c.fillRect(0, 0, 1000, 680); }
        if (precipitation < .7) {
          for (const f of fireflies) {
            const alpha = (1 - precipitation) * Math.max(0, Math.sin(time * .7 + f.phase)) * .5;
            c.fillStyle = `rgba(189,216,140,${alpha})`; c.shadowColor = '#bce786'; c.shadowBlur = 7;
            c.beginPath(); c.arc(f.x + Math.sin(time * .32 + f.phase) * 12, f.y + Math.cos(time * .45 + f.phase) * 8, 1.1, 0, TAU); c.fill(); c.shadowBlur = 0;
          }
        }
      }
      if (layers.has('foreground')) {
        for (const reed of reeds) {
          const sway = Math.sin(time * 1.4 + reed.phase) * w.wind * 8;
          c.strokeStyle = '#0a2429'; c.lineWidth = 2;
          c.beginPath(); c.moveTo(reed.x, reed.y); c.quadraticCurveTo(reed.x + 8, reed.y - reed.h * .7, reed.x + 16 + sway, reed.y - reed.h); c.stroke();
          c.strokeStyle = `rgba(85,127,119,${.32 + w.snow * .4})`; c.lineWidth = .6; c.stroke();
          if (w.snow > .1) { c.strokeStyle = `rgba(235,246,248,${w.snow})`; c.lineWidth = 2; c.beginPath(); c.moveTo(reed.x + 16 + sway, reed.y - reed.h); c.lineTo(reed.x + 14 + sway, reed.y - reed.h + 8); c.stroke(); }
        }
        const vignette = c.createRadialGradient(500, 340, 160, 500, 340, 640);
        vignette.addColorStop(0, 'rgba(0,8,17,0)'); vignette.addColorStop(1, 'rgba(0,8,17,.66)'); c.fillStyle = vignette; c.fillRect(0, 0, 1000, 680);
      }
    },
  };
  return scene satisfies SceneDefinition<ReturnType<typeof inspect>, NilkamalLayer>;
}

export function mountNilkamal(canvas: HTMLCanvasElement, options: NilkamalSceneOptions & RuntimeOptions = {}) {
  const scene = createNilkamalScene(options);
  const runtime = mountScene(canvas, scene, options);
  return { ...runtime,
    setWeather(weather: Weather) { const state = runtime.snapshot(); scene.setWeather(weather, state.paused || state.reducedMotion); runtime.invalidate(); },
    setIntensity(intensity: number) { scene.setIntensity(intensity); runtime.invalidate(); },
    setBloom(bloom: number) { scene.setBloom(bloom); runtime.invalidate(); },
    lightning() { const state = runtime.snapshot(); if (!state.reducedMotion && !state.paused) { scene.lightning(); runtime.invalidate(); } },
    reset() { scene.reset(); runtime.seek(0); },
  };
}

import { clamp, mix, TAU, type Point } from './engine/math';

type Petal = { x: number; y: number; width: number; base: number; shade: number; phase: number };
export const PETALS: readonly Petal[] = [
  { x: -165, y: -95, width: 44, base: -12, shade: .25, phase: 1 },
  { x: 165, y: -95, width: 44, base: 12, shade: .3, phase: 2 },
  { x: -110, y: -166, width: 38, base: -8, shade: .38, phase: 3 },
  { x: 110, y: -166, width: 38, base: 8, shade: .5, phase: 4 },
  { x: -55, y: -201, width: 34, base: -5, shade: .48, phase: 5 },
  { x: 55, y: -201, width: 34, base: 5, shade: .7, phase: 6 },
  { x: 0, y: -214, width: 34, base: 0, shade: .85, phase: 7 },
  { x: -193, y: -45, width: 34, base: -8, shade: .43, phase: 8 },
  { x: 193, y: -45, width: 34, base: 8, shade: .7, phase: 9 },
  { x: -134, y: -119, width: 46, base: -10, shade: .75, phase: 10 },
  { x: 134, y: -119, width: 46, base: 10, shade: .8, phase: 11 },
  { x: -67, y: -156, width: 39, base: -4, shade: .75, phase: 12 },
  { x: 67, y: -156, width: 39, base: 4, shade: 1, phase: 13 },
  { x: 0, y: -153, width: 36, base: 0, shade: .65, phase: 14 },
  { x: -140, y: -29, width: 30, base: -4, shade: .7, phase: 15 },
  { x: 140, y: -29, width: 30, base: 4, shade: .85, phase: 16 },
  { x: -94, y: -64, width: 38, base: -6, shade: .86, phase: 17 },
  { x: 94, y: -64, width: 38, base: 6, shade: 1, phase: 18 },
  { x: -36, y: -72, width: 30, base: -3, shade: .7, phase: 19 },
  { x: 36, y: -72, width: 30, base: 3, shade: .9, phase: 20 },
];

function petalPath(c: CanvasRenderingContext2D, p: Petal, bend: number) {
  const x = p.x + bend, y = p.y;
  const curl = Math.sin(p.phase * 3.7) * 3;
  c.beginPath(); c.moveTo(p.base - 7, 4);
  c.bezierCurveTo(p.base + x * .12 - p.width * 1.05, y * .14, x * .73 - p.width * .85, y * .74, x + curl, y);
  c.bezierCurveTo(x * .95 + p.width * .52, y * .74, x * .44 + p.width * 1.2, y * .13, p.base + 7, 4);
  c.quadraticCurveTo(p.base, 12, p.base - 7, 4);
  c.closePath();
}

export function drawLotus(c: CanvasRenderingContext2D, options: { time: number; wind: number; snow: number; wetness: number; bloom: number; hover: number; flash: number; pointer: Point | null; texture: CanvasPattern }) {
  const { time, wind, snow, wetness, bloom, hover, flash, pointer, texture } = options;
  c.save(); c.scale(mix(.44, 1, bloom), mix(.72, 1, bloom));
  for (const [index, original] of PETALS.entries()) {
    if (index === 14) {
      // The seed head sits behind the short front row.
      for (let i = 0; i < 45; i++) {
        const a = i * 2.399, r = Math.sqrt(i / 45) * 27;
        const x = Math.cos(a) * r, y = -41 + Math.sin(a) * r * .37;
        c.strokeStyle = 'rgba(236,202,110,.65)'; c.lineWidth = .85;
        c.beginPath(); c.moveTo(x * .65, -7); c.quadraticCurveTo(x * 1.12, y + 10, x, y - 9); c.stroke();
        c.fillStyle = i % 3 ? '#f7dda0' : '#af9f65'; c.beginPath(); c.ellipse(x, y - 9, 1.6, 2.3, 0, 0, TAU); c.fill();
      }
    }
    const localHover = pointer ? clamp(1 - Math.hypot(pointer.x - original.x * .75, pointer.y - original.y * .72) / 83) : 0;
    const p = { ...original, width: original.width * 1.14, x: original.x * mix(.16, 1, bloom), y: original.y * mix(.86, 1, bloom) - localHover * 13 };
    const bend = Math.sin(time * 1.15 + p.phase) * (1.5 + wind * 2.6) + hover * Math.sign(p.x) * 6 + localHover * Math.sign(p.x || 1) * 17;
    const x = p.x + bend;
    petalPath(c, p, bend);
    const g = c.createLinearGradient(p.base - 20, 12, x + 20, p.y);
    const light = p.shade + flash * .35;
    g.addColorStop(0, '#0b2445');
    g.addColorStop(.27, `rgb(${Math.round(11 + light * 7)},${Math.round(40 + light * 18)},${Math.round(117 + light * 28)})`);
    g.addColorStop(.65, `rgb(${Math.round(27 + light * 23)},${Math.round(84 + light * 38)},${Math.round(169 + light * 40)})`);
    g.addColorStop(.9, `rgb(${Math.round(58 + light * 36)},${Math.round(126 + light * 43)},${Math.round(201 + light * 34)})`);
    g.addColorStop(1, `rgb(${Math.round(137 + light * 34)},${Math.round(199 + light * 24)},${Math.min(255, Math.round(235 + light * 15))})`);
    c.fillStyle = g; c.fill();
    c.strokeStyle = 'rgba(153,207,236,.32)'; c.lineWidth = .7; c.stroke();
    c.save(); c.clip();
    for (let v = -7; v <= 7; v++) {
      c.strokeStyle = `rgba(177,220,246,${v === 0 ? .22 : .065 + (v % 3 === 0 ? .035 : 0)})`; c.lineWidth = v === 0 ? .7 : .4;
      c.beginPath(); c.moveTo(p.base, 7);
      c.bezierCurveTo(p.base + x * .2 + v * 3, p.y * .32, x * .78 + v * p.width * .1, p.y * .72, x, p.y + 2); c.stroke();
    }
    const sheen = c.createLinearGradient(x - p.width, p.y, x + p.width, 0);
    sheen.addColorStop(0, 'rgba(0,7,37,.24)'); sheen.addColorStop(.34, 'rgba(194,230,255,.17)'); sheen.addColorStop(.56, 'rgba(173,226,255,.025)'); sheen.addColorStop(.86, 'rgba(0,13,48,.27)');
    c.fillStyle = sheen; c.fillRect(-240, -225, 480, 250);
    c.save(); c.globalAlpha = .11; c.fillStyle = texture; c.fillRect(-240, -225, 480, 250); c.restore();
    if (wetness > .03) {
      for (let d = 0; d < 3; d++) {
        const t = .35 + d * .18, dx = x * t + Math.sin(index * 7 + d * 3) * 6, dy = p.y * t;
        const r = (1.5 + (index % 3) * .6) * wetness;
        c.fillStyle = 'rgba(126,214,255,.28)'; c.beginPath(); c.ellipse(dx, dy, r, r * 1.35, -.18, 0, TAU); c.fill();
        c.strokeStyle = 'rgba(187,240,255,.65)'; c.lineWidth = .55; c.stroke();
        c.fillStyle = '#d6f4ff'; c.beginPath(); c.arc(dx - r * .25, dy - r * .4, r * .3, 0, TAU); c.fill();
      }
    }
    if (snow > .02) {
      c.strokeStyle = `rgba(238,249,255,${clamp(snow * 3)})`; c.lineCap = 'round'; c.lineWidth = 2 + snow * 10;
      c.beginPath(); c.moveTo(x, p.y + 2);
      if (x < 0) c.bezierCurveTo(x * .73 - p.width * .85, p.y * .74, p.base + x * .12 - p.width * 1.05, p.y * .14, p.base - 7, 4);
      else c.bezierCurveTo(x * .95 + p.width * .52, p.y * .74, x * .44 + p.width * 1.2, p.y * .13, p.base + 7, 4);
      c.stroke();
      for (let d = 0; d < 10; d++) {
        const t = .45 + d * .042;
        c.fillStyle = `rgba(255,255,255,${snow * .6})`;
        c.beginPath(); c.arc(x * t + Math.sin(d * 4 + index) * p.width * .23, p.y * t, .6 + snow * 1.2, 0, TAU); c.fill();
      }
    }
    c.restore();
  }
  c.restore();
}

import { clamp, mix, randomSource, TAU, type Point } from './engine/math';

export const WEATHERS = ['clear', 'rain', 'storm', 'snow', 'hail'] as const;
export type Weather = typeof WEATHERS[number];
export type WeatherEvent = 'water' | 'lotus' | 'thunder' | 'hail' | 'ice' | 'weather';
export type WeatherState = ReturnType<typeof createWeather>;

export function createWeather(seed: number, initial: Weather, strength: number) {
  const random = randomSource(seed);
  return {
    selected: initial, intensity: clamp(strength, .2, 1),
    rain: initial === 'rain' || initial === 'storm' ? 1 : 0,
    cold: initial === 'snow' || initial === 'hail' ? 1 : 0,
    storm: initial === 'storm' ? 1 : 0,
    wind: .15, wetness: 0, snow: 0, ice: 0, flash: 0, lightningAge: 9,
    lightning: Array.from({ length: 15 }, (_, i) => ({ x: 720 + random() * 90 + Math.sin(i) * 24, y: 20 + i * 22 })),
    particles: Array.from({ length: 320 }, () => ({
      x: random() * 1200 - 100, y: random() * 680, depth: .3 + random() * .7,
      floor: 370 + random() * 300, phase: random() * TAU, kind: random(), bounce: 0,
    })),
    ripples: [] as { x: number; y: number; age: number; power: number }[],
    drops: [] as { x: number; y: number; vx: number; vy: number; age: number }[],
    nextThunder: 5, nextIce: 4, nextImpact: 0, random,
  };
}

export function stepWeather(w: WeatherState, dt: number, time: number, onEvent: (event: WeatherEvent) => void, flower: Point = { x: 500, y: 440 }) {
  const blend = 1 - Math.exp(-dt * 1.6);
  w.rain = mix(w.rain, w.selected === 'rain' || w.selected === 'storm' ? 1 : 0, blend);
  w.cold = mix(w.cold, w.selected === 'snow' || w.selected === 'hail' ? 1 : 0, blend);
  w.storm = mix(w.storm, w.selected === 'storm' ? 1 : 0, blend);
  w.wind = mix(w.wind, .12 + w.storm * 2 + (w.selected === 'hail' ? .7 : w.cold * .3), blend);
  w.wetness = clamp(w.wetness + dt * (w.rain * .15 - (1 - w.rain) * .045));
  w.snow = clamp(w.snow + dt * (w.cold * .04 * w.intensity - (1 - w.cold) * .065));
  w.ice = clamp(w.ice + dt * (w.cold * .033 * w.intensity - (1 - w.cold) * .045));
  w.flash *= Math.exp(-dt * 9);
  w.lightningAge += dt;
  w.nextThunder -= dt * w.storm;
  if (w.nextThunder <= 0 && w.storm > .6) {
    strikeLightning(w); w.nextThunder = 7 + w.random() * 9; onEvent('thunder');
  }
  w.nextIce -= dt * w.cold;
  if (w.nextIce <= 0 && w.ice > .1) { w.nextIce = 4 + w.random() * 5; onEvent('ice'); }
  w.nextImpact -= dt;
  const precipitation = Math.max(w.rain, w.cold);
  const count = Math.round(w.particles.length * precipitation * w.intensity);
  for (let i = 0; i < count; i++) {
    const p = w.particles[i]; if (!p) continue;
    const hail = w.cold > .5 && (w.selected === 'hail' || p.kind < .19);
    const speed = w.rain > .5 ? 670 : hail ? 380 : 55;
    p.x += (w.wind * 52 + (w.cold > .5 && !hail ? Math.sin(time * .9 + p.phase) * 18 : 0)) * dt * p.depth;
    p.y += (p.bounce ? p.bounce : speed * p.depth) * dt;
    if (p.bounce) p.bounce += 1000 * dt;
    if (p.y > p.floor || p.x > 1110) {
      if (hail && !p.bounce && p.x < 1060) {
        p.bounce = -100 - p.depth * 100;
        if (w.nextImpact <= 0) { onEvent('hail'); w.nextImpact = .18; }
      } else {
        if (w.rain > .4 && w.ice < .7 && w.ripples.length < 65) w.ripples.push({ x: p.x, y: p.floor, age: 0, power: p.depth });
        p.x = w.random() * 1180 - 180; p.y = -20 - w.random() * 90;
        p.floor = 370 + w.random() * 300; p.bounce = 0;
      }
    }
  }
  for (let i = w.ripples.length - 1; i >= 0; i--) {
    const p = w.ripples[i]; if (!p) continue;
    p.age += dt; if (p.age > 2.4) w.ripples.splice(i, 1);
  }
  for (let i = w.drops.length - 1; i >= 0; i--) {
    const p = w.drops[i]; if (!p) continue;
    p.age += dt; p.vy += 650 * dt; p.x += p.vx * dt; p.y += p.vy * dt;
    if (p.y > 490) {
      if (w.ripples.length < 65) w.ripples.push({ x: p.x, y: 490, age: 0, power: .7 });
      if (w.nextImpact <= 0) { onEvent('water'); w.nextImpact = .25; }
      w.drops.splice(i, 1);
    }
  }
  if (w.rain > .6 && w.random() < dt * 3 && w.drops.length < 24) {
    const side = w.random() > .5 ? 1 : -1;
    w.drops.push({ x: flower.x + side * (125 + w.random() * 50), y: flower.y - 50 + w.random() * 30, vx: side * 10, vy: 12, age: 0 });
  }
}

export function strikeLightning(w: WeatherState) {
  w.flash = 1; w.lightningAge = 0;
  for (const point of w.lightning) point.x = 690 + w.random() * 120;
}

import { clamp } from './engine/math';
import type { Weather, WeatherEvent } from './weather';

export function createNilkamalAudio(enabled = true, volume = .45) {
  let context: AudioContext | null = null, master: GainNode | null = null;
  let noise: AudioBuffer | null = null, rain: GainNode | null = null, wind: GainNode | null = null, pond: GainNode | null = null;
  let active = false, destroyed = false, selected: Weather = 'clear', intensity = .8, voices = 0, eventsPlayed = 0, lastEvent = -1;
  const loops: AudioBufferSourceNode[] = [];
  const liveVoices = new Set<AudioScheduledSourceNode>();
  const disconnects = new Map<AudioScheduledSourceNode, () => void>();

  function level(gain: GainNode | null, value: number, duration = .2) {
    if (!gain || !context) return;
    gain.gain.cancelScheduledValues(context.currentTime);
    gain.gain.setTargetAtTime(value, context.currentTime, duration);
  }

  function sync() {
    level(master, enabled && active ? clamp(volume) : 0, .08);
    level(rain, (selected === 'storm' ? .24 : selected === 'rain' ? .15 : selected === 'hail' ? .045 : selected === 'snow' ? .012 : 0) * intensity, .5);
    level(wind, (selected === 'storm' ? .3 : selected === 'snow' || selected === 'hail' ? .14 : .045) * intensity, .6);
    level(pond, selected === 'clear' ? .025 : selected === 'rain' ? .01 : 0, .4);
  }

  function bed(frequency: number, type: BiquadFilterType, q: number) {
    if (!context || !noise || !master) return null;
    const source = context.createBufferSource(), filter = context.createBiquadFilter(), gain = context.createGain();
    source.buffer = noise; source.loop = true; filter.type = type; filter.frequency.value = frequency; filter.Q.value = q;
    gain.gain.value = 0; source.connect(filter).connect(gain).connect(master); source.start(); loops.push(source);
    disconnects.set(source, () => { source.disconnect(); filter.disconnect(); gain.disconnect(); });
    return gain;
  }

  async function unlock() {
    if (!enabled || destroyed || !active) return;
    if (!context) {
      context = new AudioContext(); master = context.createGain(); master.gain.value = 0;
      const compressor = context.createDynamicsCompressor(); compressor.threshold.value = -18; compressor.ratio.value = 5;
      master.connect(compressor).connect(context.destination);
      noise = context.createBuffer(2, context.sampleRate * 4, context.sampleRate);
      for (let channel = 0; channel < 2; channel++) {
        const data = noise.getChannelData(channel); let previous = 0;
        for (let i = 0; i < data.length; i++) { previous = (previous + (Math.random() * 2 - 1) * .05) / 1.05; data[i] = previous * 4; }
      }
      rain = bed(4400, 'highpass', .3); wind = bed(260, 'lowpass', .4); pond = bed(1100, 'bandpass', 1.8);
    }
    if (context.state === 'suspended') await context.resume();
    sync();
  }

  function event(event: WeatherEvent) {
    if (!context || !master || !noise || !enabled || !active || destroyed || context.state !== 'running' || voices >= 12) return;
    const now = context.currentTime;
    if (event !== 'thunder' && now - lastEvent < .08) return;
    lastEvent = now; eventsPlayed++; voices++;
    const gain = context.createGain(), pan = context.createStereoPanner(), filter = context.createBiquadFilter();
    const noisy = event === 'thunder' || event === 'ice' || event === 'weather';
    const source = noisy ? context.createBufferSource() : context.createOscillator();
    const duration = event === 'thunder' ? 4 : event === 'ice' ? .7 : event === 'lotus' ? .8 : event === 'weather' ? .6 : .15;
    const peak = event === 'thunder' ? .6 : event === 'ice' ? .14 : event === 'lotus' ? .07 : event === 'weather' ? .055 : .045;
    if (source instanceof AudioBufferSourceNode) { source.buffer = noise; source.playbackRate.value = event === 'thunder' ? .65 : event === 'ice' ? 1.8 : 1; }
    else {
      source.type = 'sine';
      source.frequency.setValueAtTime(event === 'lotus' ? 660 : event === 'hail' ? 2300 : 1100, now);
      source.frequency.exponentialRampToValueAtTime(event === 'lotus' ? 440 : event === 'hail' ? 750 : 220, now + duration);
    }
    filter.type = noisy ? 'lowpass' : 'allpass'; filter.frequency.value = event === 'thunder' ? 180 : event === 'ice' ? 3500 : 1800;
    pan.pan.value = event === 'lotus' ? 0 : Math.random() * 1.2 - .6;
    gain.gain.setValueAtTime(.0001, now); gain.gain.exponentialRampToValueAtTime(peak, now + (event === 'thunder' ? .18 : .012));
    gain.gain.exponentialRampToValueAtTime(.0001, now + duration);
    source.connect(filter).connect(gain).connect(pan).connect(master);
    liveVoices.add(source);
    const cleanup = () => { source.disconnect(); filter.disconnect(); gain.disconnect(); pan.disconnect(); liveVoices.delete(source); disconnects.delete(source); voices = Math.max(0, voices - 1); };
    disconnects.set(source, cleanup); source.onended = cleanup; source.start(now); source.stop(now + duration + .05);
  }

  function stopVoices() {
    for (const source of [...liveVoices]) {
      source.onended = null;
      try { source.stop(); } catch {}
      disconnects.get(source)?.();
    }
  }

  return {
    unlock, event,
    setWeather(weather: Weather) { selected = weather; sync(); },
    setIntensity(value: number) { intensity = clamp(value, .2, 1); sync(); },
    setActive(value: boolean) {
      if (active === value || destroyed) return;
      active = value; sync();
      if (!value) {
        stopVoices();
        void context?.suspend().catch(() => {});
      } else if (enabled && context) void context.resume().catch(() => {});
    },
    setAudio(value: boolean, nextVolume = volume) {
      enabled = value; volume = clamp(Number.isFinite(nextVolume) ? nextVolume : .45); sync();
      if (!value) { stopVoices(); void context?.suspend().catch(() => {}); }
      else if (active && context) void context.resume().catch(() => {});
    },
    snapshot() { return { enabled, active, unlocked: Boolean(context), state: context?.state ?? 'locked', voices, eventsPlayed, volume }; },
    destroy() {
      if (destroyed) return; destroyed = true;
      for (const source of [...loops, ...liveVoices]) { source.onended = null; try { source.stop(); } catch {} disconnects.get(source)?.(); }
      disconnects.clear(); liveVoices.clear(); loops.length = 0; voices = 0;
      master?.disconnect(); void context?.close().catch(() => {}); context = null;
    },
  };
}

import { type Point, type Size } from './math';

export type HitRegion = Point & { id: string; label: string; radius: number };
export type SceneInput = { pointer: Point | null; drag: { id: string; target: Point } | null };
export type PaintState = { elapsed: number; physicalTime: number; reducedMotion: boolean; selectedId: string | null };
export type FrameState = PaintState & { paused: boolean; inView: boolean; running: boolean };

export type SceneDefinition<Details, Layer extends string> = {
  size: Size;
  layers: readonly Layer[];
  update: (elapsed: number, resetPose: boolean) => void;
  step: (dt: number, physicalTime: number, input: SceneInput) => void;
  paint: (context: CanvasRenderingContext2D, state: PaintState, layers: ReadonlySet<Layer>) => void;
  targets: () => HitRegion[];
  activate: (id: string, direction: number, physicalTime: number) => void;
  release: () => void;
  inspect: () => Details;
};

export type RuntimeOptions = {
  initialTime?: number;
  timeScale?: number;
  paused?: boolean;
  onFrame?: (state: FrameState) => void;
};

export type ExportOptions<Layer extends string> = {
  layers?: readonly Layer[];
  width?: number;
  height?: number;
};

const STEP = 1 / 120;
const MAX_STEPS = 6;

function nonnegative(value: number, label: string) {
  if (!Number.isFinite(value) || value < 0) throw new Error(`${label} must be a finite nonnegative number.`);
  return value;
}

/** Mount one scene. The host owns its surrounding layout and any persistence. */
export function mountScene<Details, Layer extends string>(canvas: HTMLCanvasElement, scene: SceneDefinition<Details, Layer>, options: RuntimeOptions = {}) {
  const maybeContext = canvas.getContext('2d');
  const host = canvas.parentElement;
  if (!maybeContext || !host) throw new Error('Mount the canvas in a positioned container with Canvas 2D support.');
  const context = maybeContext;
  let elapsed = nonnegative(options.initialTime ?? 0, 'Initial time');
  let timeScale = nonnegative(options.timeScale ?? 1, 'Time scale');
  const motionQuery = matchMedia('(prefers-reduced-motion: reduce)');
  const events = new AbortController();
  const signal = events.signal;
  const allLayers = new Set(scene.layers);
  const originalCursor = canvas.style.cursor;
  const overlay = canvas.ownerDocument.createElement('div');
  overlay.className = 'interactive-art-targets';
  Object.assign(overlay.style, { position: 'absolute', inset: '0', pointerEvents: 'none' });
  host.append(overlay);
  const buttons = new Map<string, HTMLButtonElement>();
  const directions = new Map<string, number>();
  let paused = options.paused ?? false, destroyed = false, inView = false;
  let physicalTime = 0, frame = 0, last: number | null = null, accumulator = 0, renderedFrames = 0;
  let width = 1, height = 1, scale = 1, offsetX = 0, offsetY = 0;
  let pointer: Point | null = null;
  let drag: { id: string; pointerId: number; target: Point; offset: Point; capture: HTMLElement } | null = null;

  const active = () => !destroyed && !paused && inView && !document.hidden && !motionQuery.matches;
  const paintState = (): PaintState => ({ elapsed, physicalTime, reducedMotion: motionQuery.matches, selectedId: drag?.id ?? null });

  function updateTargets() {
    const seen = new Set<string>();
    for (const target of scene.targets()) {
      seen.add(target.id);
      let button = buttons.get(target.id);
      if (!button) {
        button = canvas.ownerDocument.createElement('button');
        button.type = 'button';
        button.className = 'interactive-art-target';
        button.dataset.sceneObject = target.id;
        Object.assign(button.style, { position: 'absolute', pointerEvents: 'auto', touchAction: 'none', borderRadius: '50%', padding: '0', transform: 'translate(-50%, -50%)', background: 'transparent' });
        button.addEventListener('click', event => {
          if (event.detail !== 0 || !active()) return;
          const direction = directions.get(target.id) ?? 1;
          scene.activate(target.id, direction, physicalTime);
          directions.set(target.id, -direction);
        }, { signal });
        overlay.append(button);
        buttons.set(target.id, button);
      }
      const diameter = Math.max(44, target.radius * 2 * scale);
      const x = target.x * scale + offsetX, y = target.y * scale + offsetY;
      const visible = x + diameter / 2 > 0 && x - diameter / 2 < width && y + diameter / 2 > 0 && y - diameter / 2 < height;
      button.hidden = !visible && drag?.id !== target.id;
      button.setAttribute('aria-label', target.label);
      button.disabled = !active() || button.hidden;
      button.style.left = `${x}px`;
      button.style.top = `${y}px`;
      button.style.width = button.style.height = `${diameter}px`;
    }
    for (const [id, button] of buttons) {
      if (!seen.has(id)) { button.remove(); buttons.delete(id); }
    }
  }

  function render() {
    if (destroyed) return;
    context.setTransform(1, 0, 0, 1, 0, 0);
    context.clearRect(0, 0, canvas.width, canvas.height);
    context.setTransform(canvas.width / width * scale, 0, 0, canvas.height / height * scale, canvas.width / width * offsetX, canvas.height / height * offsetY);
    scene.paint(context, paintState(), allLayers);
    renderedFrames++;
    updateTargets();
    options.onFrame?.({ ...paintState(), paused, inView, running: active() });
  }

  function resize() {
    const rect = canvas.getBoundingClientRect();
    width = Math.max(1, rect.width);
    height = Math.max(1, rect.height);
    const density = Math.min(window.devicePixelRatio || 1, 2);
    canvas.width = Math.round(width * density);
    canvas.height = Math.round(height * density);
    scale = height / scene.size.height;
    offsetX = (width - scene.size.width * scale) / 2;
    offsetY = 0;
    render();
  }

  function localPoint(event: PointerEvent): Point {
    const rect = canvas.getBoundingClientRect();
    return { x: (event.clientX - rect.left - offsetX) / scale, y: (event.clientY - rect.top - offsetY) / scale };
  }

  function nearest(point: Point) {
    let closest: HitRegion | null = null, distance = Infinity;
    for (const target of scene.targets()) {
      const d = Math.hypot(point.x - target.x, point.y - target.y);
      if (d < Math.max(target.radius, 22 / scale) && d < distance) { closest = target; distance = d; }
    }
    return closest;
  }

  function clearInteraction() {
    const held = drag;
    drag = null;
    pointer = null;
    scene.release();
    if (held?.capture.hasPointerCapture(held.pointerId)) held.capture.releasePointerCapture(held.pointerId);
    canvas.style.cursor = originalCursor;
  }

  function tick(now: number) {
    frame = 0;
    if (!active()) return;
    const delta = last === null ? 0 : Math.min(MAX_STEPS * STEP, Math.max(0, (now - last) / 1000));
    last = now;
    accumulator += delta;
    let steps = 0;
    while (accumulator >= STEP && steps < MAX_STEPS) {
      elapsed += STEP * timeScale;
      physicalTime += STEP;
      scene.update(elapsed, false);
      scene.step(STEP, physicalTime, { pointer, drag: drag ? { id: drag.id, target: drag.target } : null });
      accumulator -= STEP;
      steps++;
    }
    render();
    if (active()) frame = requestAnimationFrame(tick);
  }

  function schedule() {
    cancelAnimationFrame(frame);
    frame = 0;
    last = null;
    accumulator = 0;
    if (active()) frame = requestAnimationFrame(tick);
  }

  host.addEventListener('pointermove', event => {
    if (!active()) return;
    const point = localPoint(event);
    if (drag?.pointerId === event.pointerId) {
      drag.target = { x: point.x - drag.offset.x, y: point.y - drag.offset.y };
      event.preventDefault();
    } else if (event.pointerType !== 'touch') {
      pointer = point;
      canvas.style.cursor = nearest(point) ? 'grab' : originalCursor;
    }
  }, { signal });
  host.addEventListener('pointerleave', () => { pointer = null; if (!drag) canvas.style.cursor = originalCursor; }, { signal });
  host.addEventListener('pointerdown', event => {
    if (event.button !== 0 || drag || !active()) return;
    const point = localPoint(event), target = nearest(point);
    if (!target) return;
    // Capture only flower targets on touch, leaving the canvas available for page scrolling.
    if (event.pointerType === 'touch' && !(event.target instanceof HTMLButtonElement)) return;
    const capture = event.target instanceof HTMLElement ? event.target : canvas;
    drag = { id: target.id, pointerId: event.pointerId, target: { x: target.x, y: target.y }, offset: { x: point.x - target.x, y: point.y - target.y }, capture };
    pointer = null;
    capture.setPointerCapture(event.pointerId);
    event.preventDefault();
  }, { signal });
  const release = (event: PointerEvent) => { if (drag?.pointerId === event.pointerId) clearInteraction(); };
  host.addEventListener('pointerup', release, { signal });
  host.addEventListener('pointercancel', release, { signal });
  host.addEventListener('lostpointercapture', release, { signal });
  document.addEventListener('visibilitychange', () => { if (document.hidden) clearInteraction(); schedule(); render(); }, { signal });
  motionQuery.addEventListener('change', () => {
    clearInteraction();
    if (motionQuery.matches) scene.update(elapsed, true);
    schedule();
    render();
  }, { signal });
  const sizeObserver = new ResizeObserver(resize);
  sizeObserver.observe(canvas);
  const visibilityObserver = new IntersectionObserver(entries => {
    const entry = entries[0];
    inView = Boolean(entry && entry.isIntersecting && entry.intersectionRatio >= .05);
    if (!inView) clearInteraction();
    schedule();
    render();
  }, { threshold: [0, .05] });
  visibilityObserver.observe(canvas);
  scene.update(elapsed, true);
  resize();

  return {
    invalidate() { render(); },
    pause() { if (destroyed) return; paused = true; clearInteraction(); schedule(); render(); },
    resume() { if (destroyed) return; paused = false; schedule(); render(); },
    setTimeScale(value: number) { if (destroyed) return; timeScale = nonnegative(value, 'Time scale'); },
    seek(seconds: number) {
      if (destroyed) return;
      elapsed = nonnegative(seconds, 'Time');
      clearInteraction();
      scene.update(elapsed, true);
      last = null;
      accumulator = 0;
      render();
    },
    bend(id: string, direction = 1) { if (active()) scene.activate(id, direction, physicalTime); },
    snapshot() {
      return { elapsed, physicalTime, timeScale, paused, inView, hidden: document.hidden, reducedMotion: motionQuery.matches, running: Boolean(frame), destroyed, renderedFrames, drag: drag?.id ?? null,
        view: { width, height, scale, offsetX, offsetY },
        targets: scene.targets().map(target => ({ ...target, screen: { x: target.x * scale + offsetX, y: target.y * scale + offsetY } })),
        details: scene.inspect() };
    },
    async exportPNG(settings: ExportOptions<Layer> = {}) {
      if (destroyed) throw new Error('Cannot export a destroyed scene.');
      const output = canvas.ownerDocument.createElement('canvas');
      const outputWidth = settings.width ?? scene.size.width, outputHeight = settings.height ?? scene.size.height;
      if (![outputWidth, outputHeight].every(value => Number.isInteger(value) && value > 0 && value <= 8192)) throw new Error('Export dimensions must be integers between 1 and 8192.');
      const selected = new Set(settings.layers ?? scene.layers);
      for (const layer of selected) if (!allLayers.has(layer)) throw new Error(`Unknown scene layer: ${layer}`);
      output.width = outputWidth;
      output.height = outputHeight;
      const outputContext = output.getContext('2d');
      if (!outputContext) throw new Error('Canvas 2D is unavailable.');
      const layerCanvas = canvas.ownerDocument.createElement('canvas');
      layerCanvas.width = outputWidth;
      layerCanvas.height = outputHeight;
      const layerContext = layerCanvas.getContext('2d');
      if (!layerContext) throw new Error('Canvas 2D is unavailable.');
      const state = { ...paintState(), selectedId: null };
      // Quantize every layer before composition, just as separate PNG assets are quantized.
      for (const layer of scene.layers) {
        if (!selected.has(layer)) continue;
        layerContext.clearRect(0, 0, outputWidth, outputHeight);
        layerContext.save();
        layerContext.scale(outputWidth / scene.size.width, outputHeight / scene.size.height);
        scene.paint(layerContext, state, new Set([layer]));
        layerContext.restore();
        outputContext.drawImage(layerCanvas, 0, 0);
      }
      return new Promise<Blob>((resolve, reject) => output.toBlob(blob => blob ? resolve(blob) : reject(new Error('PNG export failed.')), 'image/png'));
    },
    destroy() {
      if (destroyed) return;
      destroyed = true;
      cancelAnimationFrame(frame);
      frame = 0;
      clearInteraction();
      events.abort();
      sizeObserver.disconnect();
      visibilityObserver.disconnect();
      overlay.remove();
      buttons.clear();
    },
  };
}

import { mix, type Point } from './math';

type Node = Point & { previousX: number; previousY: number };

export type ElasticChain = {
  nodes: Node[];
  rest: Point[];
  lengths: number[];
  maxPull: number;
  headAngle: number;
  headVelocity: number;
};

/** A fixed root and at least two joints define an anchored elastic object. */
export function createChain(rest: Point[], maxPull: number): ElasticChain {
  if (rest.length < 2 || !Number.isFinite(maxPull) || maxPull <= 0) {
    throw new Error('An elastic chain needs two or more points and a positive pull limit.');
  }
  const chain = {
    nodes: rest.map(point => ({ ...point, previousX: point.x, previousY: point.y })),
    rest,
    lengths: rest.slice(1).map((point, index) => {
      const previous = rest[index];
      if (!previous) throw new Error('Missing chain point.');
      return Math.hypot(point.x - previous.x, point.y - previous.y);
    }),
    maxPull,
    headAngle: 0,
    headVelocity: 0,
  };
  resetChain(chain);
  return chain;
}

export function resetChain(chain: ElasticChain) {
  for (let index = 0; index < chain.nodes.length; index++) {
    const node = chain.nodes[index], rest = chain.rest[index];
    if (!node || !rest) continue;
    node.x = node.previousX = rest.x;
    node.y = node.previousY = rest.y;
  }
  const a = chain.nodes.at(-2), b = chain.nodes.at(-1);
  if (a && b) chain.headAngle = Math.atan2(b.y - a.y, b.x - a.x) + Math.PI / 2;
  chain.headVelocity = 0;
}

/** Growth changes the rest geometry, independently of the simulation clock. */
export function updateRest(chain: ElasticChain, rest: Point[], reset = false) {
  if (rest.length !== chain.nodes.length) throw new Error('The chain joint count must stay constant.');
  chain.rest = rest;
  for (let index = 1; index < rest.length; index++) {
    const a = rest[index - 1], b = rest[index];
    if (a && b) chain.lengths[index - 1] = Math.hypot(b.x - a.x, b.y - a.y);
  }
  if (reset) resetChain(chain);
}

export function boundedTarget(chain: ElasticChain, point: Point): Point {
  const rest = chain.rest.at(-1);
  if (!rest) throw new Error('Missing chain tip.');
  const dx = point.x - rest.x, dy = point.y - rest.y;
  const distance = Math.hypot(dx, dy);
  const ratio = distance > chain.maxPull ? chain.maxPull / distance : 1;
  return { x: rest.x + dx * ratio, y: rest.y + dy * ratio };
}

/** Fixed-step Verlet integration, length constraints, and a separately damped head. */
export function simulateChain(chain: ElasticChain, dt: number, time: number, wind: number, target: Point | null) {
  const root = chain.nodes[0], anchor = chain.rest[0], tipRest = chain.rest.at(-1);
  if (!root || !anchor || !tipRest) return;
  const goal = target ? boundedTarget(chain, target) : null;
  const damping = Math.exp(-(goal ? 11 : 5.8) * dt);
  root.x = root.previousX = anchor.x;
  root.y = root.previousY = anchor.y;
  for (let index = 1; index < chain.nodes.length; index++) {
    const node = chain.nodes[index], rest = chain.rest[index];
    if (!node || !rest) continue;
    const progress = index / (chain.nodes.length - 1);
    const velocityX = (node.x - node.previousX) * damping;
    const velocityY = (node.y - node.previousY) * damping;
    node.previousX = node.x;
    node.previousY = node.y;
    const gust = (Math.sin(time * .85 + anchor.x * .006) * 22 + Math.sin(time * 1.9 + progress) * 6) * wind * progress;
    const goalX = goal ? rest.x + (goal.x - tipRest.x) * progress ** 2 : rest.x;
    const goalY = goal ? rest.y + (goal.y - tipRest.y) * progress ** 2 : rest.y;
    const stiffness = goal ? 105 : 48;
    node.x += velocityX + ((goalX - node.x) * stiffness + gust) * dt * dt;
    node.y += velocityY + (goalY - node.y) * stiffness * dt * dt;
  }
  for (let pass = 0; pass < 10; pass++) {
    for (let index = 1; index < chain.nodes.length; index++) {
      const a = chain.nodes[index - 1], b = chain.nodes[index], length = chain.lengths[index - 1];
      if (!a || !b || length === undefined) continue;
      const dx = b.x - a.x, dy = b.y - a.y;
      const distance = Math.max(.001, Math.hypot(dx, dy));
      const correction = (distance - length) / distance;
      if (index > 1) { a.x += dx * correction * .5; a.y += dy * correction * .5; }
      const share = index === 1 ? 1 : .5;
      b.x -= dx * correction * share;
      b.y -= dy * correction * share;
    }
    const tip = chain.nodes.at(-1);
    if (tip) Object.assign(tip, boundedTarget(chain, tip));
  }
  const a = chain.nodes.at(-2), b = chain.nodes.at(-1);
  if (a && b) {
    const angle = Math.atan2(b.y - a.y, b.x - a.x) + Math.PI / 2;
    chain.headVelocity += ((angle - chain.headAngle) * 42 - chain.headVelocity * 7.8) * dt;
    chain.headAngle += chain.headVelocity * dt;
  }
}

/** Attach an ornament at a fractional joint position, using the current tangent. */
export function attachment(chain: ElasticChain, progress: number) {
  const position = Math.max(0, Math.min(1, progress)) * (chain.nodes.length - 1);
  const index = Math.min(Math.floor(position), chain.nodes.length - 2);
  const a = chain.nodes[index], b = chain.nodes[index + 1];
  if (!a || !b) throw new Error('Missing attachment joints.');
  return { x: mix(a.x, b.x, position - index), y: mix(a.y, b.y, position - index), angle: Math.atan2(b.y - a.y, b.x - a.x) + Math.PI / 2 };
}

export function chainSnapshot(chain: ElasticChain) {
  const root = chain.nodes[0], tip = chain.nodes.at(-1), rest = chain.rest.at(-1);
  if (!root || !tip || !rest) throw new Error('Missing chain geometry.');
  return {
    root: { x: root.x, y: root.y },
    tip: { x: tip.x, y: tip.y },
    rest: { ...rest },
    maxPull: chain.maxPull,
    maxSegmentError: Math.max(...chain.nodes.slice(1).map((node, index) => {
      const previous = chain.nodes[index], length = chain.lengths[index];
      if (!previous || !length) return 0;
      return Math.abs(Math.hypot(node.x - previous.x, node.y - previous.y) / length - 1);
    })),
  };
}

export type Point = { x: number; y: number };
export type Size = { width: number; height: number };

export const TAU = Math.PI * 2;
export const clamp = (value: number, low = 0, high = 1) => Math.max(low, Math.min(high, value));
export const mix = (a: number, b: number, amount: number) => a + (b - a) * amount;

export function smooth(value: number) {
  const t = clamp(value);
  return t * t * (3 - 2 * t);
}

export function randomSource(seed: number) {
  let state = seed >>> 0;
  return () => {
    state = (Math.imul(state, 1664525) + 1013904223) >>> 0;
    return state / 4294967296;
  };
}

export type RGB = readonly [number, number, number];

export function colour(from: RGB, to: RGB, amount: number, alpha = 1) {
  return `rgba(${from.map((channel, index) => Math.round(mix(channel, to[index] ?? channel, amount))).join(',')},${alpha})`;
}

.nilkamal-scene { position: relative; aspect-ratio: 1000 / 680; overflow: clip; background: #081724; isolation: isolate; }
.nilkamal-scene canvas { position: relative; display: block; width: 100%; height: 100%; touch-action: pan-y; }
.nilkamal-fallback { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; }
.nilkamal-scene .interactive-art-target { border: 1px solid transparent; cursor: grab; }
.nilkamal-scene .interactive-art-target:active { cursor: grabbing; }
.nilkamal-scene .interactive-art-target:focus-visible { outline: 2px solid #c0e7fb; outline-offset: 3px; }
.nilkamal-scene .interactive-art-target:disabled { cursor: default; }
@media (max-width: 520px) { .nilkamal-scene { aspect-ratio: 4 / 5; } }
